"""URL slugs for titles."""
import re
import unicodedata


def slugify(title, max_length=None):
    """Lower-case ASCII words joined by hyphens."""
    if max_length is not None and max_length < 1:
        raise ValueError("max_length must be at least 1")

    text = unicodedata.normalize("NFKD", title)
    text = "".join(ch for ch in text if not unicodedata.combining(ch)).lower()
    slug = re.sub(r"[^a-z0-9]+", "-", text).strip("-")
    slug = slug or "untitled"

    if max_length is None or len(slug) <= max_length:
        return slug

    # Need to shorten the slug to fit within max_length
    words = slug.split("-")
    result = ""

    for word in words:
        if not result:
            # First word
            if len(word) <= max_length:
                result = word
            else:
                # First word is too long, cut it to exactly max_length
                return word[:max_length]
        else:
            # Check if we can add the next word
            new_result = result + "-" + word
            if len(new_result) <= max_length:
                result = new_result
            else:
                # Can't add this word, stop here
                break

    return result


def unique_slug(title, taken, max_length=None):
    """Return a slug unique within the taken collection."""
    if max_length is not None and max_length < 1:
        raise ValueError("max_length must be at least 1")

    base = slugify(title, max_length)

    if base not in taken:
        return base

    # Try suffixes -2, -3, etc. until we find one not in taken
    counter = 2
    while True:
        suffix = f"-{counter}"

        if max_length is not None:
            # Need to fit suffix + base within max_length
            available_for_base = max_length - len(suffix)
            if available_for_base < 1:
                raise ValueError("max_length too small for suffix")

            # Recalculate the base with the reduced max_length
            candidate_base = slugify(title, available_for_base)
            candidate = candidate_base + suffix
        else:
            candidate = base + suffix

        if candidate not in taken:
            return candidate

        counter += 1
